INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (97536,0,0,0,0,'I''ve slapped on some labels that say hazardous and toxic... that way people know to leave them be after you find them a new home in the desert.',71037);
