INSERT INTO `quest_request_items` (`ID`,`EmoteOnComplete`,`EmoteOnIncomplete`,`EmoteOnCompleteDelay`,`EmoteOnIncompleteDelay`,`CompletionText`,`VerifiedBuild`) VALUES (92872,0,0,0,0,'Even this place of solemn death has an influx of new matter. Releasing it back into the light in such a manner is meant to represent the draw towards the seeds of new life.',71037);
