INSERT INTO `quest_template` (`ID`,`QuestType`,`QuestSortID`,`QuestInfoID`,`RewardNextQuest`,`RewardXPDifficulty`,`RewardXPMultiplier`,`RewardMoneyDifficulty`,`RewardMoneyMultiplier`,`RewardSpell`,`StartItem`,`Flags`,`FlagsEx`,`FlagsEx2`,`TimeAllowed`,`AllowableRaces`,`LogTitle`,`LogDescription`,`QuestDescription`,`AreaDescription`,`QuestCompletionLog`,`VerifiedBuild`) VALUES (96979,2,616,0,0,2,1.0,0,1.0,0,275991,35651584,0,0,0,18446744073709551615,'Sacred Refreshment','Fill Galvinquam Leafsyre''s drinking gourd at the waterfall ahead.','I am a druid of the Circle, walking the long path to honor the great world tree. I misjudged how much the climb would ask of me, and the winged hunters that haunt these slopes have made caution a necessity. These old ruins offered shelter, and I accepted it.
